from collections import Counter
def comps(g,c):
    seen=set(); res=[]
    for i,r in enumerate(g):
        for j,v in enumerate(r):
            if v==c and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); cc=[]
                while st:
                    p=st.pop(); cc.append(p)
                    for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                        q=(p[0]+di,p[1]+dj)
                        if 0<=q[0]<len(g) and 0<=q[1]<len(g[0]) and g[q[0]][q[1]]==c and q not in seen:
                            seen.add(q); st.append(q)
                res.append(cc)
    return res
