def max_rect(g,c,bg):
    # brute force: max area rectangle fully color c or bg
    H,W=len(g),len(g[0]); best=(0,0,0)
    for i in range(H):
        for j in range(W):
            v=g[i][j]
            if v not in (c,bg): continue
            for di in range(i,H):
                for dj in range(j,W):
                    if any(g[r][q]!=v for r in range(i,di+1) for q in range(j,dj+1)): break
                    best=(max(best[0],(di-i+1)*(dj-j+1)),i,j)
    return best
